package com.mockarena.runner.config;

import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.beans.factory.annotation.*; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.web.*; import java.nio.charset.StandardCharsets; import java.security.MessageDigest;
@Configuration public class RunnerSecurityConfiguration {
 @Bean SecurityFilterChain security(HttpSecurity http,ObjectMapper json,@Value("${runner.security.enabled:true}")boolean enabled,@Value("${runner.security.workload-token:}")String token)throws Exception{if(enabled&&(token==null||token.isBlank()))throw new IllegalStateException("Runner workload token required when security is enabled");return http.csrf(c->c.disable()).addFilterBefore(new TokenFilter(token,enabled),org.springframework.security.web.authentication.AnonymousAuthenticationFilter.class).authorizeHttpRequests(a->a.requestMatchers("/actuator/health/**").permitAll().requestMatchers("/internal/**").permitAll().anyRequest().denyAll()).build();}
 static final class TokenFilter extends org.springframework.web.filter.OncePerRequestFilter {private final String token;private final boolean enabled;TokenFilter(String t,boolean e){token=t;enabled=e;}protected boolean shouldNotFilter(jakarta.servlet.http.HttpServletRequest r){return !r.getRequestURI().startsWith("/internal/");}protected void doFilterInternal(jakarta.servlet.http.HttpServletRequest r,jakarta.servlet.http.HttpServletResponse s,jakarta.servlet.FilterChain c)throws java.io.IOException,jakarta.servlet.ServletException{String actual=r.getHeader("X-MockArena-Workload-Token");if(enabled&&(actual==null||!MessageDigest.isEqual(token.getBytes(StandardCharsets.UTF_8),actual.getBytes(StandardCharsets.UTF_8)))){s.sendError(401);return;}c.doFilter(r,s);}}
}
